@js:

var base = String(baseUrl);
function pick(txt) {
  var i = txt.indexOf('id="cont-body"');
  if (i < 0) { return ''; }
  var j = txt.indexOf('>', i) + 1;
  var k = txt.indexOf('</div>', j);
  if (k < 0) { k = txt.length; }
  return txt.substring(j, k);
}
function maxPage(txt) {
  var mx = 1, p = 0, i, j, d, c, n;
  while ((i = txt.indexOf('_', p)) >= 0) {
    j = i + 1; d = '';
    while (j < txt.length) {
      c = txt.charAt(j);
      if (c >= '0' && c <= '9') { d = d + c; j = j + 1; } else { break; }
    }
    if (d.length > 0) {
      if (txt.substring(j, j + 5) == '.html') {
        n = parseInt(d, 10);
        if (n > mx) { mx = n; }
      }
    }
    p = i + 1;
  }
  return mx;
}
// 若当前就是 _N.html，归一到第一页
var cut = base.lastIndexOf('.html');
var pre = cut > 0 ? base.substring(0, cut) : base;
var us = pre.lastIndexOf('_');
if (us > 0) {
  var tail = pre.substring(us + 1);
  var allNum = true;
  for (var q = 0; q < tail.length; q++) {
    var cc = tail.charAt(q);
    if (cc < '0' || cc > '9') { allNum = false; break; }
  }
  if (allNum) { pre = pre.substring(0, us); }
}
var first = pre + '.html';
var h = String(java.ajax(first));
var out = pick(h);
var mp = maxPage(h);
if (mp > 1) {
  var parts = [out];
  for (var p = 2; p <= mp; p = p + 1) {
    var ph = '';
    try { ph = String(java.ajax(pre + '_' + p + '.html')); } catch (e) { ph = ''; }
    if (ph.length > 0) { parts.push(pick(ph)); }
  }
  out = parts.join('');
}
// 去 script 段
var res = '', pos = 0, si, se;
while (true) {
  si = out.indexOf('<script', pos);
  if (si < 0) { res = res + out.substring(pos); break; }
  res = res + out.substring(pos, si);
  se = out.indexOf('</script>', si);
  if (se < 0) { break; }
  pos = se + 9;
}
result = res;
